            "day2_event2_desc"
          ]
        },
        {
          "id": "day2_event2_title",
          "component": "Text",
          "variant": "h4",
          "text": "8:30 AM - 9:30 AM: Sannenzaka & Ninenzaka"
        },
        {
          "id": "day2_event2_transit",
          "component": "Text",
          "text": "Transit: 5 min walk from Kiyomizu-dera's exit."
        },
        {
          "id": "day2_event2_desc",
          "component": "Text",
          "text": "Wander down these beautifully preserved stone-paved streets before the shops open and the crowds arrive. The lack of people allows for clean shots of traditional Japanese architecture."
        },
